219	int	validate_syntax(t_shell *shell, t_token *tokens)
220	{
221		if (is_invalid_char(shell->input))
222			return (ERR_INVALID);
223		if (is_unclosed_quotes(shell->input))
224			return (ERR_UNCLOSED_QUOTES);
225		if (tokens && tokens->type == PIPE)
226			return (ERR_PIPE_START);
227		while (tokens && tokens->next)
228		{
229			if (validate_redir(tokens) != SYNTAX_OK)
230				return (ERR_REDIR_EOF);
231			if (tokens->type == PIPE && tokens->next->type == PIPE)
232				return (ERR_PIPE_DOUBLE);
233			tokens = tokens->next;
234		}
235		if (tokens && (tokens->type == REDIR_IN || tokens->type == REDIR_OUT
236				|| tokens->type == APPEND || tokens->type == HEREDOC))
237			return (ERR_REDIR_EOF);
238		if (tokens && tokens->type == PIPE)
239			return (ERR_PIPE_EOF);
240		return (SYNTAX_OK);
241	}
