590	static char	*process_quote_content(char *result, char **input, char quote)
591	{
592		char	*tmp;
593		char	c[2];
594	
595		c[1] = '\0';
596		while (**input && **input != quote)
597		{
598			c[0] = **input;
599			tmp = ft_strjoin(result, c);
600			free(result);
601			result = tmp;
602			(*input)++;
603		}
604		return (result);
605	}
