607	char	*append_quoted_part(char **input, char *result, char quote)
608	{
609		result = add_quote_marker(result, quote, input);
610		result = process_quote_content(result, input, quote);
611		if (**input != quote)
612			return (free(result), NULL);
613		return (add_end_marker(result, input));
614	}
