701	int	process_token(t_token **c_tkn, t_cmd **c_cmd, t_cmd **cmds)
702	{
703		if ((*c_tkn)->type == WORD)
704			handle_word_token_parse(*c_tkn, *c_cmd);
705		else if ((*c_tkn)->type == REDIR_IN || (*c_tkn)->type == REDIR_OUT
706			|| (*c_tkn)->type == APPEND || (*c_tkn)->type == HEREDOC)
707			handle_redir_token_parse(c_tkn, *c_cmd);
708		else if ((*c_tkn)->type == PIPE)
709		{
710			if (!handle_pipe_token_parse(c_cmd, cmds))
711				return (0);
712		}
713		return (1);
714	}
