1280	static int	digit_len(int n)
1281	{
1282		int	i;
1283	
1284		i = 1;
1285		if (n == 0)
1286			return (1);
1287		if (n < 0)
1288		{
1289			n = -n;
1290			i++;
1291		}
1292		while (n / 10 > 0)
1293		{
1294			n = n / 10;
1295			i++;
1296		}
1297		return (i);
1298	}
