1300	static char	*ft_swap(char *str)
1301	{
1302		char	tmp;
1303		int		i;
1304		int		j;
1305	
1306		i = 0;
1307		if (str[0] == '-')
1308			i = 1;
1309		j = ft_strlen(str) - 1;
1310		while (i < j)
1311		{
1312			tmp = str[i];
1313			str[i] = str[j];
1314			str[j] = tmp;
1315			i++;
1316			j--;
1317		}
1318		return (str);
1319	}
