1322	{
1323		int		j;
1324		char	*str;
1325	
1326		j = 0;
1327		if (n == -2147483648)
1328			return (ft_strdup("-2147483648"));
1329		str = (char *)malloc(sizeof(char) * (digit_len(n) + 1));
1330		if (!str)
1331			return (NULL);
1332		if (n < 0)
1333		{
1334			str[j++] = '-';
1335			n = -n;
1336		}
1337		while (n > 9)
1338		{
1339			str[j] = (n % 10) + 48;
1340			n /= 10;
1341			j++;
1342		}
1343		if (n < 10)
1344			str[j++] = n + 48;
1345		str[j] = '\0';
1346		ft_swap(str);
1347		return (str);
1348	}
