fn to_string(v: Vec<u8>) -> String {
    String::from_utf8(v).unwrap_or_else(|e| String::from_utf8_lossy(e.as_bytes()).into_owned())
}

/// C `lexer()`. Returns `None` where the C function returns NULL (unclosed quote, or no tokens at all).
pub fn lexer(input: &str) -> Option<Vec<Token>> {
    let b = input.as_bytes();
    let mut i = 0;
    let mut tokens: Vec<Token> = Vec::new();
    let op = |ty, v: &str| Token { ty, value: v.to_string(), quoted: 0 };
    while i < b.len() {
        while i < b.len() && is_space(b[i]) {
            i += 1;
        }
        let c = b.get(i).copied().unwrap_or(0);
        let n = b.get(i + 1).copied().unwrap_or(0);
        if c == b'|' {
            tokens.push(op(TokenType::Pipe, "|"));
            i += 1;
        } else if c == b'>' && n == b'>' {
            tokens.push(op(TokenType::Append, ">>"));
            i += 2;
        } else if c == b'>' {
            tokens.push(op(TokenType::RedirOut, ">"));
            i += 1;
        } else if c == b'<' && n == b'<' {
            tokens.push(op(TokenType::Heredoc, "<<"));
            i += 2;
        } else if c == b'<' {
            tokens.push(op(TokenType::RedirIn, "<"));
            i += 1;
        } else {
            let mut word: Vec<u8> = Vec::new();
            let mut quoted = 0;
            while i < b.len() && !is_space(b[i]) && !matches!(b[i], b'|' | b'<' | b'>') {
                let ch = b[i];
                if ch == b'"' || ch == b'\'' {
                    if ch == b'\'' {
                        quoted = 1;
                    }
                    word.push(if ch == b'\'' { 1 } else { 2 });
                    i += 1;
                    while i < b.len() && b[i] != ch {
                        word.push(b[i]);
                        i += 1;
                    }
                    if i >= b.len() {
                        return None;
                    }
                    word.push(3);
                    i += 1;
                } else {
                    word.push(ch);
                    i += 1;
                }
            }
            if !word.is_empty() {
                tokens.push(Token { ty: TokenType::Word, value: to_string(word), quoted });
            }
        }
    }
    if tokens.is_empty() {
        None
    } else {
        Some(tokens)
    }
}

fn is_invalid_char(input: &str) -> bool {
    let mut in_quote = false;
    let mut quote_char = 0u8;
    for &c in input.as_bytes() {
        if (c == b'"' || c == b'\'') && !in_quote {
            in_quote = true;
            quote_char = c;
        } else if c == quote_char && in_quote {
            in_quote = false;
            quote_char = 0;
        } else if !in_quote && (c == b';' || c == b'\\') {
            return true;
        }
    }
    false
}

fn is_unclosed_quotes(input: &str) -> bool {
    let mut quote = 0u8;
    for &c in input.as_bytes() {
        if (c == b'"' || c == b'\'') && quote == 0 {
            quote = c;
        } else if c == quote {
            quote = 0;
        }
    }
    quote != 0
}

fn is_redir(t: TokenType) -> bool {
    matches!(t, TokenType::RedirIn | TokenType::RedirOut | TokenType::Append | TokenType::Heredoc)
}

/// C `validate_syntax()`; `shell.input` is the line that was lexed. Returns SYNTAX_OK or an ERR_* code.
pub fn validate_syntax(shell: &Shell, tokens: &[Token]) -> i32 {
    if is_invalid_char(&shell.input) {
        return ERR_INVALID;
    }
    if is_unclosed_quotes(&shell.input) {
        return ERR_UNCLOSED_QUOTES;
    }
    if let Some(t) = tokens.first() {
        if t.ty == TokenType::Pipe {
            return ERR_PIPE_START;
        }
    }
    for w in tokens.windows(2) {
        if is_redir(w[0].ty) && w[1].ty == TokenType::Pipe {
            return ERR_REDIR_EOF;
        }
        if w[0].ty == TokenType::Pipe && w[1].ty == TokenType::Pipe {
            return ERR_PIPE_DOUBLE;
        }
    }
    if let Some(t) = tokens.last() {
        if is_redir(t.ty) {
            return ERR_REDIR_EOF;
        }
        if t.ty == TokenType::Pipe {
            return ERR_PIPE_EOF;
        }
    }
    SYNTAX_OK
}

/// C `parser()`: tokens -> commands (one per pipeline segment).
pub fn parser(tokens: &[Token]) -> Vec<Cmd> {
    let mut cmds = Vec::new();
    let mut cur = Cmd::default();
    let mut i = 0;
    while i < tokens.len() {
        let t = &tokens[i];
        if t.ty == TokenType::Word {
            if t.quoted == 1 {
                cur.argv.push(format!("\u{1}{}", t.value));
            } else {
                cur.argv.push(t.value.clone());
            }
        } else if is_redir(t.ty) {
            if let Some(n) = tokens.get(i + 1) {
                cur.redir.push(Redir { ty: t.ty, file: n.value.clone() });
            }
            i += 1;
        } else if t.ty == TokenType::Pipe {
            cmds.push(std::mem::take(&mut cur));
        }
        i += 1;
    }
    cmds.push(cur);
    cmds
}

fn lookup_env<'a>(env: &'a [String], key: &[u8]) -> Option<&'a str> {
